-- Expert distractors for the existing bank, plus new questions with a full
-- obvious / plausible / tricky ladder. Apply after the app reads choices.tier.
insert into ltf.choices (question_id, label, body, is_correct, rationale, sort_order, tier)
select q.id, 'D', v.body, false, v.rationale, v.sort_order, 3
from ltf.questions q join (values
  ('oop-category-1-rotating-parts', 'A label identifying it as eligible for Category 1 operations', 'Only Category 2 and 3 aircraft must carry an eligibility label. Category 1 has no labeling requirement.', 4),
  ('oop-category-1-weight', '0.55 pounds or less, not counting the battery', 'The weight includes everything on board or attached at takeoff, battery included.', 4),
  ('oop-category-2-energy', '15 foot-pounds', 'No category uses 15. Category 2 is 11 foot-pounds and Category 3 is 25.', 4),
  ('oop-category-3-energy', '55 foot-pounds', 'Category 3 is 25 foot-pounds. 55 is the pound limit for a small unmanned aircraft, not an energy figure.', 4),
  ('oop-category-3-restrictions', 'Only over people who have signed a written consent form', 'Category 3 turns on a closed site where everyone is on notice, or no sustained flight over people. Written consent is not the test.', 4),
  ('oop-category-4', 'It has an FAA-accepted declaration of compliance', 'A declaration of compliance is the Category 2 and 3 route. Category 4 needs a Part 21 airworthiness certificate.', 4),
  ('oop-damaged-label', 'Carry a printed copy of the declaration of compliance in place of the label', 'The label belongs on the aircraft. If it is unreadable, the remote pilot must re-label it before the operation.', 4),
  ('oop-declaration-of-compliance', 'A record accepted by the FAA certifying an aircraft is eligible for Category 4', 'Category 4 relies on an airworthiness certificate, not a declaration of compliance.', 4),
  ('oop-means-of-compliance', 'Test and inspection only; analysis is not accepted', '107.155 accepts test, analysis, or inspection, alone or in combination.', 4),
  ('oop-moving-vehicles', 'Remain in a closed site with notice, or stay at least 50 feet above the vehicle', 'There is no altitude alternative. Outside a closed site, flight over moving vehicles must be transient, not sustained.', 4),
  ('oop-open-air-assembly', 'Categories 1 and 2 only, where Remote ID requirements are also met', 'Category 4 may also operate over open-air assemblies. Category 3 is the only category barred.', 4),
  ('oop-variable-modes', 'The remote pilot must notify the FAA before switching modes', 'No notice is required. The design must simply prevent the pilot from switching modes by accident.', 4),
  ('reg-adsb-out-prohibition', 'ADS-B Out is permitted only in Class B or C airspace', '107.53 prohibits ADS-B Out in transmit mode in all airspace unless otherwise authorized.', 4),
  ('reg-alt-400-structure', '1,100 feet AGL, provided you remain within a 500-foot radius of the tower', 'The lateral limit is a 400-foot radius, not 500.', 4),
  ('reg-applicability-exclusions', 'Commercial flights of an aircraft weighing 0.55 pounds or less', 'Part 107 applies to commercial flying at any weight. 0.55 pounds matters for registration exceptions and Category 1, not applicability.', 4),
  ('reg-certificate-possession', 'You must present it, but only if the officer is a federal agent', '107.7 lets federal, state, and local law enforcement officers all request it.', 4),
  ('reg-change-of-address', '14 days', '14 days is the retest wait after a failed knowledge test. The address window is 30 days.', 4),
  ('reg-civil-twilight-definition', 'The period beginning at sunset and ending when the sun is 12 degrees below the horizon', '12 degrees marks nautical twilight. Outside Alaska, Part 107 uses the fixed 30-minute window.', 4),
  ('reg-cloud-clearance', '500 feet below, 1,000 feet above, and 2,000 feet horizontally', 'That is the manned VFR minimum in much of Class E and G. Part 107 sets only 500 feet below and 2,000 feet horizontally.', 4),
  ('reg-controlled-airspace-auth', 'A Certificate of Waiver issued under 107.200', 'Class B, C, D, and surface Class E need ATC authorization under 107.41. A waiver covers waivable rules, not airspace access.', 4),
  ('reg-direct-supervision', 'Under direct supervision, but only after the assistant has passed the knowledge test', 'No test is required. What matters is that the rPIC can immediately take direct control.', 4),
  ('reg-dropping-object', 'Only when the object weighs less than 0.55 pounds', '107.23(b) has no weight test. The test is whether dropping it creates an undue hazard.', 4),
  ('reg-drug-conviction', 'Denial of an application for up to 1 year, with no effect on a certificate already held', '107.57 also allows suspension or revocation of a certificate already held.', 4),
  ('reg-eligibility-age', '16 years old, or 18 to fly for compensation', 'There is no separate age for commercial work. 16 is the single minimum.', 4),
  ('reg-hazmat', 'Yes, with a waiver issued under 107.200', '107.36 is not a waivable section. No waiver can authorize hazardous material under Part 107.', 4),
  ('reg-inflight-emergency', 'The rPIC may deviate from any rule, but must file a written report within 10 days', 'A written report is due only if the Administrator requests one, under 107.21(b).', 4),
  ('reg-knowledge-recency', 'By completing recurrent training within the previous 12 calendar months', 'The recency window is 24 calendar months.', 4),
  ('reg-max-groundspeed', '100 knots (87 miles per hour)', 'The units are swapped. The limit is 87 knots, which is 100 miles per hour.', 4),
  ('reg-medical-condition', 'You may serve as visual observer, but not as rPIC', '107.17 bars you from acting as rPIC, visual observer, or manipulating the controls.', 4),
  ('reg-min-visibility', '5 statute miles, measured from the control station', 'The minimum is 3 statute miles.', 4),
  ('reg-moving-vehicle', 'Only over a sparsely populated area, and only with a visual observer in the vehicle', 'No visual observer is required. The second condition is that you may not carry another person''s property for hire.', 4),
  ('reg-multiple-aircraft', 'Three, provided each weighs 0.55 pounds or less', 'Weight does not change 107.35. One person may operate one aircraft at a time.', 4),
  ('reg-night-lighting', 'Anti-collision lighting visible for at least 5 statute miles', 'The rule sets 3 statute miles.', 4),
  ('reg-over-human-beings', 'A person inside a moving vehicle with a hard roof', 'The exception covers a covered structure or a stationary vehicle. A moving vehicle is treated separately.', 4),
  ('reg-preflight-assessment', 'Local weather and airspace, plus a written weight and balance computation', '107.49 requires assessing weather, airspace, and people and property on the surface. No weight and balance computation is mandated.', 4),
  ('reg-refusal-alcohol-test', 'Automatic, permanent revocation of the certificate', '107.59 allows denial for up to 1 year, or suspension or revocation. Nothing is automatic or permanent.', 4),
  ('reg-restricted-area-permission', 'Permission from the nearest Flight Standards District Office', 'The using or controlling agency grants access, not an FSDO.', 4),
  ('reg-retest-after-failure', '7 calendar days', 'The wait is 14 calendar days.', 4),
  ('reg-right-of-way', 'The small unmanned aircraft yields only to manned aircraft in controlled airspace', '107.37 requires yielding to all aircraft, in any airspace.', 4),
  ('reg-rpic-final-authority', 'The visual observer, while the aircraft is out of the rPIC''s sight', 'Final authority never transfers to a visual observer.', 4),
  ('reg-safety-event-threshold', 'A report to the FAA within 30 calendar days', 'The window is 10 calendar days.', 4),
  ('reg-safety-event-window', 'Within 10 business days', 'The rule counts calendar days, not business days.', 4),
  ('reg-suas-definition-weight', '55 pounds or less on takeoff, including everything on board', 'A small unmanned aircraft weighs less than 55 pounds. Exactly 55 is not small.', 4),
  ('reg-temporary-certificate', '90 calendar days', 'A temporary certificate is issued for up to 120 calendar days.', 4),
  ('reg-transponder-prohibition', 'No, unless operating within 5 miles of an airport', 'Proximity to an airport does not change the rule. Only the Administrator can authorize transponder use.', 4),
  ('reg-visual-observer-comms', 'The crew must use handheld radios on an aviation frequency', 'Any effective means of communication is acceptable. Radios are not mandated.', 4),
  ('reg-vlos-corrective-lenses', 'Corrective lenses, or binoculars when a visual observer is also watching', 'No device other than corrective lenses may be used to satisfy visual line of sight, whoever holds it.', 4),
  ('rid-adsb-cannot-comply', 'Yes, provided a transponder is also installed', 'Neither ADS-B Out nor a transponder can satisfy Remote ID.', 4),
  ('rid-aeronautical-research', 'When the operation is solely for news gathering', '89.101 limits the exception to aeronautical research or showing compliance with regulations.', 4),
  ('rid-broadcast-duration', 'From motor start until the aircraft lands', 'The broadcast must run from takeoff all the way to shutdown, not just until landing.', 4),
  ('rid-broadcast-method', 'Radio broadcast from the control station on behalf of the aircraft', 'The aircraft itself broadcasts the message elements.', 4),
  ('rid-broadcast-module-difference', 'It reports control station location rather than takeoff location, and cannot be used beyond visual line of sight', 'That swaps them. A module reports the takeoff location; standard Remote ID reports the control station.', 4),
  ('rid-fria', 'An area where aircraft without Remote ID may be flown beyond visual line of sight', 'Inside a FRIA, aircraft without Remote ID must stay within visual line of sight.', 4),
  ('rid-fria-eligibility', 'A recognized community-based organization, an educational institution, or a local government', '89.205 makes community-based organizations and educational institutions the only eligible applicants.', 4),
  ('rid-identity-element', 'The serial number of the control station', 'Identity is the aircraft''s serial number or a session ID, not the control station.', 4),
  ('rid-loss-in-flight', 'Land immediately, wherever the aircraft is', 'The rule says as soon as practicable, which allows choosing a safe place to land.', 4),
  ('rid-module-no-emergency-status', 'The altitude of the unmanned aircraft', 'A broadcast module does report aircraft altitude. Emergency status is what it omits.', 4),
  ('rid-preflight-self-test', 'Automatically self-test, and warn the pilot but still allow takeoff if it fails', 'A standard Remote ID aircraft must not be able to take off unless Remote ID is functioning.', 4),
  ('rid-registration-serial', 'The serial number of the remote pilot''s control station', 'The registration must list the broadcast module''s serial number.', 4),
  ('rid-standard-message-elements', 'The position of the aircraft and its takeoff location, velocity, and time mark', 'That is a broadcast module. Standard Remote ID reports control station position and emergency status.', 4),
  ('rid-three-options', 'Standard Remote ID, a broadcast module, or network Remote ID through an approved provider', 'Network Remote ID was dropped from the final rule.', 4),
  ('waiver-application', 'Through the FAA DroneZone, after holding the certificate for 6 months', 'No minimum experience period exists. Applicants show the operation can be done safely.', 4),
  ('waiver-not-waivable', 'The prohibition on operating from a moving vehicle', '107.25 is waivable. Hazardous material under 107.36 is not.', 4),
  ('air-basic-weather-minimums', '3 statute miles visibility, 500 feet below and 1,000 feet horizontally from clouds', 'The horizontal clearance is 2,000 feet.', 4),
  ('air-class-b-shape', 'Dashed magenta lines', 'Dashed magenta marks Class E beginning at the surface.', 4),
  ('air-class-c-depiction', 'A shaded magenta vignette', 'A magenta vignette marks Class E beginning at 700 feet AGL.', 4),
  ('air-class-d-depiction', 'A shaded blue vignette', 'A blue vignette marks Class E beginning at 1,200 feet AGL.', 4),
  ('air-class-e-700', '700 feet MSL', 'The vignette floor is 700 feet above ground level, not mean sea level.', 4),
  ('air-class-e-surface', 'Class D airspace that reverts to Class E when the tower closes', 'Class D is drawn as a dashed blue line. Dashed magenta is Class E to the surface.', 4),
  ('air-class-g-authorization', 'None, unless within 5 statute miles of an airport', 'Part 107 has no 5-mile rule in Class G. You must only avoid interfering with airport traffic.', 4),
  ('air-controlled-firing-area', 'They are charted only on terminal area charts', 'They are not charted at all, because activity stops when aircraft approach.', 4),
  ('air-laanc', 'A request through FAA DroneZone, which is the usual near-real-time route', 'DroneZone requests can take weeks. LAANC is the near-real-time route.', 4),
  ('air-laser-illumination', 'Report it to local police only; the FAA tracks only manned aircraft', 'The FAA asks for reports of all laser illuminations, including of unmanned aircraft.', 4),
  ('air-manned-aircraft-lighting', 'It is crossing from your right to your left', 'Seeing both red and green at once means the aircraft is pointed at you.', 4),
  ('air-moa', 'Airspace where civil flight requires permission from the controlling agency', 'That describes a restricted area. MOAs need no permission, though caution is advised.', 4),
  ('air-mtr-digits', 'The route is flown under IFR at or below 1,500 feet AGL', 'VR means VFR. Four digits mean no segment above 1,500 feet AGL.', 4),
  ('air-notam', 'Permanent information that is already printed on charts', 'NOTAMs carry time-critical information that is not yet charted.', 4),
  ('air-nsa', 'Airspace where flight requires permission from the Department of Homeland Security', 'NSAs request voluntary avoidance. Flight can be temporarily prohibited only by NOTAM.', 4),
  ('air-operations-near-airports', 'No authorization, but you must remain below 200 feet AGL', 'There is no special altitude in Class G near an airport. The rule is not to interfere with traffic.', 4),
  ('air-precipitation-static', 'Static charge that builds on the remote pilot and damages the controller', 'P-static builds on the aircraft as it moves through precipitation.', 4),
  ('air-prohibited-area', 'Airspace where flight is prohibited only while a NOTAM is active', 'That describes a TFR. Prohibited areas are permanent.', 4),
  ('air-restricted-area', 'Restricted areas require ATC authorization through LAANC', 'LAANC does not cover restricted areas. Permission comes from the using or controlling agency.', 4),
  ('air-sUAS-lighting-requirement', 'Anti-collision lighting visible for at least 3 nautical miles', 'The rule says statute miles.', 4),
  ('air-tfr', 'Check B4UFLY once when planning the job', 'TFRs can appear at short notice. Check NOTAMs before every flight, not just at planning.', 4),
  ('air-thermal-plumes', 'They produce strong downdrafts, but only on the downwind side', 'The main hazard is rising, turbulent air directly above them.', 4),
  ('air-trsa', 'An area where radar sequencing is mandatory for all VFR aircraft', 'Participation in a TRSA is voluntary.', 4),
  ('air-uas-facility-map', 'You may fly there up to 100 feet AGL without requesting authorization', 'The number is the most ATC will routinely approve. You still need the authorization.', 4),
  ('air-unlit-ground-hazards', 'Lighted obstruction towers taller than 200 feet AGL', 'Tall towers carry obstruction lights. The hazard is the unlit structures below them.', 4),
  ('air-unmanned-balloons', 'Their radar reflectors interfere with the control link', 'The hazard is the nearly invisible line and payload hanging below.', 4),
  ('air-warning-area', 'Airspace from 12 NM outward from the coast containing hazardous activity', 'Warning areas begin 3 NM from the coast.', 4),
  ('air-wire-environment', 'Wires are highest at mid-span, between the support structures', 'Wires sag. They are lowest at mid-span and highest at the structures.', 4),
  ('load-attachment-security', 'That it is secure and weighs less than 10 percent of the aircraft', 'There is no 10 percent rule. It must be secure and not affect flight characteristics or controllability.', 4),
  ('load-battery-cold', 'Reduced capacity, but improved ability to deliver current under load', 'Cold reduces both capacity and the ability to deliver current.', 4),
  ('load-cg-effect', 'The aircraft becomes more stable but less maneuverable', 'Outside limits, both stability and control margin suffer.', 4),
  ('load-endurance-planning', 'As a reliable figure once 10 percent is subtracted', 'Wind, temperature, payload, and battery age can cut far more than 10 percent.', 4),
  ('load-flight-time-reserve', 'Enough for 30 minutes of additional flight, matching manned VFR day reserves', 'Part 107 sets no reserve. 30 minutes is the manned VFR day rule in 91.151.', 4),
  ('load-max-takeoff-weight', 'That the total is under 55 pounds and the CG is recorded in a log', 'No log is required. The manufacturer''s maximum takeoff weight is the limit that matters here.', 4),
  ('load-performance-data', 'It replaces the need for a preflight assessment', 'Performance data informs the preflight assessment. It does not replace it.', 4),
  ('load-stability-definition', 'The ability to hold an attitude the pilot commands', 'That describes controllability. Stability is the tendency to return after a disturbance.', 4),
  ('load-weight-effect', 'Reduced flight time, but a faster climb from the added momentum', 'Added weight slows the climb.', 4),
  ('load-wind-power-demand', 'It increases only during the climb, then returns to normal', 'Holding position or progress against a headwind demands extra power the whole time.', 4),
  ('wx-advection-fog', 'Moist air moving up a slope and cooling', 'That is upslope fog.', 4),
  ('wx-asos-awos', 'Automated stations that issue forecasts for the next 24 hours', 'They report observations, not forecasts.', 4),
  ('wx-ceiling-definition', 'The height of the lowest scattered, broken, or overcast layer', 'Scattered layers do not form a ceiling.', 4),
  ('wx-cold-front', 'Gradually lowering clouds and steady rain ahead of the front', 'That describes a warm front.', 4),
  ('wx-density-altitude-definition', 'Indicated altitude corrected for non-standard temperature', 'The correction starts from pressure altitude, not indicated altitude.', 4),
  ('wx-density-altitude-effect', 'Reduced lift, but longer flight time because motors draw less current', 'Thin air makes motors work harder and shortens flight time.', 4),
  ('wx-icing-conditions', 'Visible moisture and an air temperature below minus 20 degrees Celsius', 'Icing needs only visible moisture and freezing temperatures. It is most common between 0 and minus 20 degrees Celsius.', 4),
  ('wx-lightning-distance', 'At least 10 nautical miles', 'The guidance is at least 20 nautical miles.', 4),
  ('wx-metar-altimeter', 'An altimeter setting of 299.2 hectopascals', 'The A prefix means inches of mercury. A Q prefix would mean hectopascals.', 4),
  ('wx-metar-cavok-clr', 'Thunderstorms are likely because the spread is small', 'A small spread signals saturation, meaning fog or low cloud, not instability.', 4),
  ('wx-metar-definition', 'A forecast of conditions within 5 statute miles of an airport', 'That is a TAF. A METAR is an observation.', 4),
  ('wx-metar-sky-cover', 'OVC only', 'A broken layer also constitutes a ceiling.', 4),
  ('wx-metar-wind', 'Wind from 210 degrees magnetic at 15 knots, gusting to 25 knots', 'METAR wind direction is referenced to true north, not magnetic.', 4),
  ('wx-microburst', 'A small, intense updraft lasting up to an hour', 'A microburst is a downdraft, usually lasting under 15 minutes.', 4),
  ('wx-radiation-fog', 'Clear skies, strong wind, and high humidity overnight', 'Strong wind mixes the air and lifts it into low stratus instead of fog.', 4),
  ('wx-stable-air', 'Smooth air, cumuliform clouds, and showery precipitation', 'Cumuliform clouds and showers mark unstable air.', 4),
  ('wx-taf-definition', 'A forecast for approximately 5 nautical miles around an airport', 'TAFs cover 5 statute miles.', 4),
  ('wx-thunderstorm-mature-stage', 'The mature stage, marked by the anvil top first appearing', 'The mature stage begins when precipitation falls from the cloud base.', 4),
  ('wx-thunderstorm-stages', 'Towering, mature, anvil', 'The three stages are cumulus, mature, and dissipating.', 4),
  ('wx-unstable-air', 'Turbulence, stratiform clouds, steady precipitation, and good visibility', 'Stratiform clouds and steady precipitation mark stable air.', 4),
  ('wx-weather-briefing-source', 'The METAR alone, since it is an official observation', 'A METAR shows current conditions only. A briefing also needs forecasts and advisories.', 4),
  ('wx-wind-gradient-obstacles', 'It becomes turbulent mostly on the upwind side', 'The rotors and downdrafts form on the downwind side.', 4),
  ('ops-airport-beacon', 'A lighted heliport', 'Heliports flash green, yellow, and white.', 4),
  ('ops-airport-types', 'An airport whose control tower operates part time', 'Airports with a part-time tower are still charted in blue.', 4),
  ('ops-alcohol-8-hours', 'No operation within 8 hours, or at or above 0.08 percent BAC', 'The limit is 0.04 percent.', 4),
  ('ops-atis', 'Weather updated every minute by an automated sensor', 'That describes ASOS or AWOS. ATIS is a recorded broadcast, updated hourly or when things change.', 4),
  ('ops-chart-supplement', 'The UAS Facility Map', 'Facility Maps show authorization altitudes, not runway or frequency data.', 4),
  ('ops-crm-definition', 'Sharing authority equally so no single person is the final authority', 'CRM never removes the remote pilot in command''s final authority.', 4),
  ('ops-ctaf-purpose', 'A frequency on which a ground station sequences arriving traffic', 'No one sequences traffic on CTAF. Pilots self-announce.', 4),
  ('ops-dark-adaptation', 'About 10 minutes', 'Cones adapt in roughly 10 minutes. Full rod adaptation takes about 30.', 4),
  ('ops-dehydration', 'It impairs judgment, but only once you notice thirst', 'Thirst is a late sign. Impairment starts before you feel it.', 4),
  ('ops-emergency-planning', 'Lost link behaviour and a safe landing area, filed with the FAA before flight', 'No filing is required. The plan is for the crew.', 4),
  ('ops-fatigue', 'It degrades attention, but is easy to recognize in yourself', 'Fatigue is hard to self-detect, which is what makes it dangerous.', 4),
  ('ops-frequency-interference', 'GPS multipath reflections off the antennas', 'Multipath degrades position, not the control link.', 4),
  ('ops-gps-loss', 'The aircraft switches to attitude mode and holds its position', 'Attitude mode does not hold position. The aircraft drifts with the wind.', 4),
  ('ops-hazardous-attitude-antiauthority', 'Macho', 'Macho is about proving yourself. Rejecting rules is anti-authority.', 4),
  ('ops-hazardous-attitude-macho', 'Invulnerability', 'Invulnerability is "it won''t happen to me." Showing off for a rival is macho.', 4),
  ('ops-hazardous-attitude-resignation', 'Resignation; the antidote is "Follow the rules. They are usually right"', 'That is the antidote to anti-authority. Resignation''s is "I am not helpless."', 4),
  ('ops-hyperventilation', 'Too little carbon dioxide, corrected by breathing pure oxygen', 'Extra oxygen does not help. Slowing the breathing restores carbon dioxide.', 4),
  ('ops-imsafe', 'The pilot''s fitness and the aircraft''s airworthiness together', 'IMSAFE covers only the pilot. PAVE covers the aircraft.', 4),
  ('ops-lithium-charging', 'Charge on a non-flammable surface with any charger rated for the pack voltage', 'Use the specified charger and stay with it.', 4),
  ('ops-lithium-thermal-runaway', 'Thermal runaway, which stops once the pack is unplugged from the charger', 'Thermal runaway sustains itself. Unplugging does not stop it.', 4),
  ('ops-lithium-transport', 'Protect the terminals and store packs fully charged to prevent cell damage', 'Partial charge is safer for storage and transport.', 4),
  ('ops-lost-link', 'The return-to-home altitude should be set to exactly 400 feet AGL', 'Return-to-home altitude must clear local obstacles. There is no fixed correct value.', 4),
  ('ops-maintenance-records', 'Keep records only for repairs done by the manufacturer', 'Record all maintenance, repairs, and replacements, whoever does them.', 4),
  ('ops-maintenance-who', 'Anyone, provided they hold a remote pilot certificate', 'Part 107 sets no certificate requirement for maintenance.', 4),
  ('ops-mechanical-mitigation', 'Have an FAA repair station inspect the aircraft annually', 'No annual inspection exists. Follow the manufacturer''s maintenance guidance.', 4),
  ('ops-night-vision-off-center', 'Look 30 to 40 degrees off to the side of the object', 'The guidance is 5 to 10 degrees off center.', 4),
  ('ops-otc-medication', 'It is acceptable if you feel no drowsiness after the first dose', 'Impairment can be present without feeling it, and the illness itself matters.', 4),
  ('ops-phonetic-alphabet', 'Kilo Dog Alfa Lima', 'D is Delta. Dog comes from a retired alphabet.', 4),
  ('ops-preflight-inspection', 'Airframe and propellers, battery, and a return-to-home test at full range', 'A full-range RTH test is not part of a preflight inspection.', 4),
  ('ops-preflight-night', 'Verify the anti-collision lighting works and is visible for 1 statute mile', 'The lighting must be visible for 3 statute miles.', 4),
  ('ops-radio-phraseology-altitude', 'An altitude of 2,500 feet above ground level', 'Manned pilots report altitude above mean sea level.', 4),
  ('ops-risk-assessment', 'It removes the need to reassess conditions once on site', 'Conditions change. The advance assessment sets limits; it does not replace looking.', 4),
  ('ops-runway-markings-displaced', 'A displaced threshold usable for taxi only', 'Displaced thresholds are marked with arrows, not chevrons.', 4),
  ('ops-runway-number-heading', 'Approximately 275 to 284 degrees', 'Runway 27 covers about 265 to 274 degrees. 275 to 284 would be runway 28.', 4),
  ('ops-self-announce', 'The aircraft is on downwind, about to turn base for runway 18', 'It is already on base and about to turn final.', 4),
  ('ops-sida', 'An area where visitors must be escorted but staff need no identification', 'Everyone in a SIDA must display identification.', 4),
  ('ops-situational-awareness', 'Listening to the visual observer''s callouts while flying', 'A visual observer''s callouts add awareness. Fixating on a screen removes it.', 4),
  ('ops-situational-awareness', 'Keeping the aircraft close enough to see its orientation', 'Close range helps you keep the aircraft and its orientation in view.', 5),
  ('ops-stress', 'It broadens attention, so more information is processed', 'Acute stress narrows attention.', 4),
  ('ops-task-management', 'Working tasks in checklist order regardless of urgency', 'Task management means prioritizing by urgency, not fixed order.', 4),
  ('ops-team-communication', 'Clear roles, with only the remote pilot allowed to call a stop', 'Anyone on the crew should be empowered to call a stop.', 4),
