  ('ops-traffic-pattern-direction', 'Left turns, except at towered airports, where turns are right', 'Standard patterns use left turns at towered and non-towered airports alike.', 4),
  ('ops-unicom', 'A government flight service frequency for weather briefings', 'UNICOM is a non-government station.', 4),
  ('ops-vision-factors', 'Wearing non-polarized sunglasses', 'Sunglasses cut glare and help. Looking toward the sun is the bigger problem.', 4),
  ('ops-vision-factors', 'Flying at dusk with anti-collision lights on', 'Lights make the aircraft easier to see, not harder.', 5),
