  ('ops2-heatstroke', 'Shivering, slurred speech, and confusion', 'Those are signs of hypothermia.', 4),
  ('ops2-impulsivity', 'Anti-authority', 'Anti-authority is rejecting rules. Acting without thinking is impulsivity.', 4),
  ('ops2-invulnerability', 'Macho', 'Macho is proving yourself. "It only happens to careless people" is invulnerability.', 4),
  ('ops2-lithium-characteristics', 'A high power-to-weight ratio from a non-flammable electrolyte', 'LiPo electrolyte is flammable.', 4),
  ('ops2-lithium-safe-usage', 'Respect minimum voltage, and recharge while still warm to lower resistance', 'Let packs cool before recharging.', 4),
  ('ops2-medication-timing', 'Fly only after a pharmacist confirms the medication is FAA-approved', 'No such approval exists for Part 107 pilots. You judge your own fitness.', 4),
  ('ops2-n-number', 'The aircraft''s model year and serial number', '"Seven two five romeo alpha" is the N-number registration.', 4),
  ('ops2-night-illusions', 'The graveyard spiral', 'That is a vestibular illusion felt inside a manned cockpit.', 4),
  ('ops2-noise-distraction', 'Answer briefly while the aircraft holds a GPS hover', 'Your attention belongs on the aircraft. Let crew handle bystanders.', 4),
  ('ops2-pave-checklist', 'Pilot, Airspace, Visibility, External pressures', 'A and V are Aircraft and enVironment.', 4),
  ('ops2-procedures-at-night', 'Rely on obstacle avoidance sensors to find unlit obstacles', 'Many sensors work poorly in the dark. Survey the site in daylight.', 4),
  ('ops2-procedures-over-people', 'Fly lower so any impact carries less energy', 'Lower does not move people out of the fall zone.', 4),
  ('ops2-propeller-inspection', 'Cracks and chips, which can be sanded smooth before flight', 'Damaged propellers should be replaced, not repaired.', 4),
  ('ops2-record-retention-value', 'They are needed to renew registration every 3 years', 'Registration renewal does not require maintenance records.', 4),
  ('ops2-sectional-chart-purpose', 'Showing the TFRs active during the chart''s effective dates', 'TFRs are issued by NOTAM and are not charted.', 4),
  ('ops2-towered-vs-not', 'Pilots self-separate at a towered field; a controller sequences at a non-towered field', 'That is backwards.', 4),
  ('ops2-vertigo-spatial', 'When the aircraft flies away from the pilot, inputs appear reversed', 'Flying away, inputs match. Facing the pilot, they reverse.', 4),
  ('ops2-visual-observer-value', 'It transfers responsibility for collision avoidance to the observer', 'The remote pilot in command keeps final authority and responsibility.', 4)
) as v(slug, body, rationale, sort_order) on q.slug = v.slug;

insert into ltf.questions (slug, stem, explanation, acs_element_code, difficulty, citation, is_free, is_active) values
  ('reg-falsification', 'A remote pilot changes the completion date on a recurrent training record. What may result?', '107.5 makes any fraudulent or intentionally false record, or an altered certificate or record, grounds to suspend or revoke any certificate, rating, authorization, or waiver the person holds.', 'UA.I.A.K3', 'medium', '14 CFR 107.5', true, true),
  ('reg-records-on-request', 'An FAA inspector asks to see documents you are required to keep under Part 107. What must you do?', '107.7 requires the remote pilot in command, owner, or person at the controls to make the remote pilot certificate and any other document, record, or report required by the regulations available to the Administrator on request.', 'UA.I.A.K7', 'medium', '14 CFR 107.7', true, true),
  ('reg-registration-any-weight', 'You fly a 0.4 pound drone for a paid real estate shoot. Must it be registered?', 'Part 48''s exception for aircraft 0.55 pounds or less applies only to recreational flying. Any aircraft flown under Part 107 must be registered, whatever it weighs.', 'UA.I.B.K1', 'hard', '14 CFR 48.15', true, true),
  ('reg-registration-marking', 'Where must the FAA registration number be displayed on a small unmanned aircraft?', 'Since February 2019 the registration number must be legible on an external surface of the aircraft. Inside a battery compartment no longer satisfies the rule.', 'UA.I.B.K1', 'medium', '14 CFR 48.205', true, true),
  ('reg-condition-for-safe-operation', 'Who must check that the small UAS is in a condition for safe operation before each flight?', '107.15 makes the remote pilot in command responsible for checking the system before each flight, and prohibits operating it when it is not safe.', 'UA.I.B.K2', 'easy', '14 CFR 107.15', true, true),
  ('reg-careless-reckless', 'A remote pilot makes low passes over a crowded beach to impress friends. Which rule is most directly violated?', '107.23(a) prohibits operating a small UAS in a careless or reckless manner so as to endanger the life or property of another.', 'UA.I.B.K6a', 'easy', '14 CFR 107.23', true, true),
  ('reg-alcohol-timing', 'You had one beer at 10 p.m. Your shoot launches at 7 a.m. the next morning. May you act as a crew member?', 'Part 107 applies 91.17: no acting as a crew member within 8 hours of drinking, or with a blood alcohol concentration of 0.04 percent or more. Both conditions must be met; 9 hours have passed, so you may fly if you are below 0.04.', 'UA.I.B.K8', 'medium', '14 CFR 107.27; 14 CFR 91.17', true, true),
  ('reg-night-requirements', 'What does a remote pilot need to fly at night under Part 107 today?', 'Since April 2021, 107.29 allows night operations without a waiver if the pilot has passed the updated knowledge test or completed the updated training, and the aircraft has anti-collision lighting visible for 3 statute miles.', 'UA.I.B.K9', 'medium', '14 CFR 107.29', true, true),
  ('reg-property-for-hire', 'A client wants to pay you to deliver a package by drone. Which condition applies under Part 107?', 'Part 107 allows carrying property for compensation if the total weight with cargo is under 55 pounds, the flight stays within visual line of sight, it is not from a moving vehicle, and it stays within one state.', 'UA.I.B.K26', 'hard', 'AC 107-2A; 14 CFR 107.3', true, true),
  ('reg-automated-flight', 'Your aircraft flies a preprogrammed mapping mission on autopilot. What does Part 107 require of you?', 'Automated flight is allowed under Part 107, but the remote pilot in command must be able to intervene and change the flight path, and visual line of sight must still be maintained.', 'UA.I.B.K23', 'medium', '14 CFR 107.19; 14 CFR 107.31', true, true),
  ('reg-tfr-overrides-laanc', 'You hold a LAANC authorization for a job site. A VIP TFR is then issued covering it. What applies?', '107.47 requires compliance with flight restrictions designated by NOTAM. A LAANC authorization grants controlled airspace access; it does not override a TFR.', 'UA.I.B.K19', 'hard', '14 CFR 107.47; 14 CFR 91.141', true, true),
  ('reg-airport-interference', 'What does 107.43 prohibit near airports?', '107.43 prohibits operating a small UAS in a way that interferes with operations and traffic patterns at any airport, heliport, or seaplane base.', 'UA.I.B.K17', 'medium', '14 CFR 107.43', true, true),
  ('reg-right-of-way-passing', 'Besides yielding right of way, what does 107.37 require around other aircraft?', '107.37 requires the small UAS to yield to all aircraft and not pass over, under, or ahead of one unless well clear.', 'UA.I.B.K14a', 'medium', '14 CFR 107.37', true, true),
  ('reg-certificate-requirements', 'Which of the following is required to obtain a remote pilot certificate?', 'An applicant must be at least 16, read, speak, write and understand English, be in a condition to fly safely, pass the initial knowledge test, and clear TSA security vetting. There is no flight test and no medical certificate.', 'UA.I.B.K22', 'easy', '14 CFR 107.61', true, true),
  ('oop-night-over-people', 'What additional equipment requirement applies to operations over people at night?', 'Operations over people at night are allowed under the categories, but the aircraft must have lit anti-collision lighting visible for at least 3 statute miles, and the pilot must meet the updated night training or test.', 'UA.I.E.K2', 'hard', '14 CFR 107.29', true, true),
  ('oop-kinetic-energy-measure', 'How does Part 107 express the Category 2 injury threshold?', 'Category 2 aircraft must not cause injury equal to or greater than the severity caused by a rigid object transferring 11 foot-pounds of kinetic energy on impact.', 'UA.I.E.K16', 'hard', '14 CFR 107.120', true, true),
  ('oop-no-fixed-distance', 'What minimum lateral distance from a non-participating person does Part 107 set for Category 2 operations?', 'Subpart D sets no fixed distance. Eligibility over people comes from the aircraft''s category and its operating limits, not a set buffer.', 'UA.I.E.K5', 'hard', '14 CFR 107 Subpart D', true, true),
  ('oop-operating-instructions', 'What must the producer of a Category 2 or 3 aircraft make available to its owner?', 'Producers must provide remote pilot operating instructions describing how to operate the aircraft within its eligibility, alongside the declaration of compliance and label.', 'UA.I.E.K9', 'hard', '14 CFR 107.125', true, true),
  ('air-who-authorizes', 'Who issues authorizations to fly in Class B, C, D, or surface Class E airspace under Part 107?', 'Authorization comes from air traffic control, usually through LAANC, or through FAA DroneZone where LAANC is not available.', 'UA.II.A.K4', 'easy', '14 CFR 107.41', true, true),
  ('air-accident-causes', 'What most often contributes to aircraft accidents, including small UAS mishaps?', 'Across aviation, most accidents trace to human factors: decisions, procedures, and attention, rather than mechanical failure alone.', 'UA.II.B.K4a', 'medium', 'FAA-H-8083-25; FAA-H-8083-2', true, true),
  ('air-obstacle-agl', 'On a sectional chart, an obstruction shows 1549 in bold with (349) beneath it. What does 349 indicate?', 'The bold number is the top of the obstruction in feet MSL. The number in parentheses is its height above ground level.', 'UA.II.B.K7', 'medium', 'FAA Aeronautical Chart User''s Guide', true, true),
  ('air-night-equipment', 'What personal equipment helps a remote pilot during a night operation?', 'A dimmable or red flashlight lets you read checklists and handle equipment while preserving night vision, which takes about 30 minutes to rebuild.', 'UA.II.B.K6', 'medium', 'FAA-H-8083-25', true, true),
  ('wx-tornadoes', 'Tornadoes are most often associated with what kind of weather?', 'Most strong tornadoes come from severe thunderstorms, particularly rotating supercells.', 'UA.III.B.K1f', 'easy', 'FAA-H-8083-28', true, true),
  ('wx-hail-outside', 'Where can hail be encountered relative to a thunderstorm?', 'Hail can fall from the anvil into clear air miles from the storm core, so clear air near a storm is not safe.', 'UA.III.B.K1h', 'medium', 'FAA-H-8083-28', true, true),
  ('wx-surface-analysis', 'What does a surface analysis chart show?', 'A surface analysis shows observed fronts, high and low pressure centers, isobars, and station data at the chart time.', 'UA.III.A.K4', 'medium', 'FAA-H-8083-28', true, true),
  ('wx-prog-chart', 'What is a short-range surface prognostic chart used for?', 'Prog charts forecast where fronts, pressure systems, and precipitation will be at set times ahead.', 'UA.III.A.K4', 'medium', 'FAA-H-8083-28', true, true),
  ('wx-heat-performance', 'How does a hot day affect a multirotor''s performance?', 'Hot air is less dense, so propellers make less thrust per revolution. Motors and the battery work harder, and flight time drops.', 'UA.III.B.K1', 'medium', 'FAA-H-8083-25', true, true),
  ('wx-dewpoint-spread', 'A METAR shows 18/06. What is the temperature-dewpoint spread, and what does it suggest?', '18 minus 6 is a 12 degree Celsius spread. The air is far from saturation, so fog is unlikely.', 'UA.III.B.K1i', 'medium', 'FAA-H-8083-28', true, true),
  ('wx-metar-visibility', 'In a METAR, what does 1/2SM FG report?', 'SM is statute miles and FG is fog. Visibility is one-half statute mile in fog.', 'UA.III.A.K2', 'easy', 'AIM 7-1; FAA-H-8083-28', true, true),
  ('wx-metar-ceiling-height', 'In a METAR, what does BKN008 report?', 'Cloud heights are reported in hundreds of feet AGL. BKN008 is a broken layer at 800 feet AGL, which forms a ceiling.', 'UA.III.A.K2', 'medium', 'AIM 7-1; FAA-H-8083-28', true, true),
  ('wx-taf-fm', 'In a TAF, what does FM1600 mean?', 'FM marks a rapid and lasting change. FM1600 means from 1600 UTC, the conditions that follow apply.', 'UA.III.A.K3', 'medium', 'AIM 7-1; FAA-H-8083-28', true, true),
  ('wx-taf-prob', 'What does PROB30 mean in a TAF?', 'PROB30 gives a 30 percent probability of the thunderstorms or precipitation that follow during the stated period.', 'UA.III.A.K3', 'medium', 'AIM 7-1; FAA-H-8083-28', true, true),
  ('wx-warm-front', 'What weather is typical ahead of an approaching warm front?', 'Warm fronts slope gently. Clouds lower gradually and steady precipitation falls over a wide area ahead of the front, often with poor visibility.', 'UA.III.B.K1d', 'medium', 'FAA-H-8083-28', true, true),
  ('wx-inversion', 'What is a temperature inversion, and what does it often produce near the ground?', 'In an inversion, temperature rises with height. The stable layer traps smoke, haze, and moisture, often reducing visibility.', 'UA.III.B.K1c', 'medium', 'FAA-H-8083-28', true, true),
  ('wx-ridge-wind', 'Wind blows steadily across a ridge. What should you expect on the downwind (lee) side?', 'Air rises on the windward side and sinks with turbulence on the lee side.', 'UA.III.B.K1b', 'medium', 'FAA-H-8083-28', true, true),
  ('load-bank-load-factor', 'What happens to load factor as bank angle increases in a level turn?', 'Load factor rises with bank angle, slowly at first and then steeply past about 45 degrees. The structure and motors carry more load.', 'UA.IV.A.K1a', 'medium', 'FAA-H-8083-25', true, true),
  ('load-60-degree-bank', 'In a level 60 degree bank, what is the load factor?', 'Load factor in a level turn is 1 divided by the cosine of the bank angle. At 60 degrees it is 2 G.', 'UA.IV.A.K1a', 'medium', 'FAA-H-8083-25', true, true),
  ('load-offset-payload', 'A camera is mounted off center on a multirotor. What is the likely effect?', 'An off-center load moves the CG. Some motors must work harder to hold level, reducing endurance and leaving less control margin.', 'UA.IV.A.K1b', 'medium', 'FAA-H-8083-25', true, true),
  ('load-high-elevation', 'You launch from a site at 7,000 feet MSL. Compared with sea level, what should you expect?', 'Air at 7,000 feet is much less dense. Propellers produce less thrust per revolution, motors work harder, and flight time drops.', 'UA.IV.A.K2', 'medium', 'FAA-H-8083-25', true, true),
  ('load-voltage-sag', 'Why can a battery reading 30 percent trigger a low-voltage landing during a hard climb?', 'Voltage sags under heavy current draw. The aircraft can read the sag as a depleted battery and force a landing.', 'UA.IV.A.K2', 'hard', 'FAA-H-8083-25', true, true),
  ('load-wind-limit', 'The manufacturer rates the aircraft for 24 mph wind. Winds are 20 gusting 30 mph. What is the sound decision?', 'Gusts are what the aircraft has to survive. With gusts above the rated limit, don''t fly.', 'UA.IV.A.K2', 'medium', 'FAA-H-8083-2', true, true),
  ('load-damaged-prop', 'How does a nicked propeller affect performance?', 'Damage reduces thrust efficiency and adds vibration that can upset the flight controller''s sensors.', 'UA.IV.A.K2', 'easy', 'FAA-H-8083-25', true, true),
  ('ops-ctaf-inbound-call', 'You hear "Rockwall traffic, Cessna three four tango, five miles south, inbound for landing runway one seven." Where should you look?', 'The aircraft is 5 miles south and heading toward the airport to land on runway 17.', 'UA.V.A.K3', 'medium', 'AIM 4-1-9', true, true),
  ('ops-wind-sock', 'An airport wind sock is fully extended. What wind speed does that suggest?', 'A standard wind cone is fully extended at about 15 knots or more.', 'UA.V.B.K3', 'easy', 'AIM 2-3-14; FAA-H-8083-25', true, true),
  ('ops-pattern-legs', 'In order after takeoff, what are the legs of a standard traffic pattern?', 'Departure or upwind, crosswind, downwind, base, then final.', 'UA.V.B.K4', 'medium', 'AIM 4-3-2', true, true),
  ('ops-macho-antidote', 'What is the antidote to the macho hazardous attitude?', 'Each hazardous attitude has an antidote. For macho it is "Taking chances is foolish."', 'UA.V.D.K4', 'easy', 'FAA-H-8083-2', true, true),
  ('ops-imsafe-s', 'In the IMSAFE checklist, what does the S stand for?', 'IMSAFE is Illness, Medication, Stress, Alcohol, Fatigue, and Emotion.', 'UA.V.E.K7', 'easy', 'FAA-H-8083-25', true, true),
  ('ops-swollen-lipo', 'A LiPo pack is noticeably swollen after a flight. What should you do?', 'Swelling means internal damage and gas buildup. Retire the pack and dispose of it through a battery recycler.', 'UA.V.C.K2c', 'easy', 'FAA-H-8083-25; manufacturer guidance', true, true),
  ('ops-rth-tree-line', 'Return-to-home altitude is set to 80 feet. A 120 foot tree line stands between you and the aircraft. What happens on a lost link?', 'Return-to-home climbs only to the set altitude, then flies straight back. At 80 feet it can fly into a 120 foot tree line.', 'UA.V.C.K3', 'medium', 'FAA-H-8083-2; manufacturer guidance', true, true),
  ('ops-3p-model', 'What does the 3P model for managing risk stand for?', 'Perceive the hazards, Process them by evaluating risk, and Perform by acting to reduce it.', 'UA.V.D.K1', 'medium', 'FAA-H-8083-2', true, true),
  ('ops-crew-briefing', 'What should a preflight crew briefing cover?', 'Brief roles, the flight plan, emergency procedures, and agreed calls so everyone knows what to do before something goes wrong.', 'UA.V.D.K1a', 'easy', 'FAA-H-8083-2', true, true),
  ('ops-compass-calibration', 'Why calibrate a drone''s compass away from vehicles and steel structures?', 'Nearby steel distorts the local magnetic field, so calibration there bakes in a wrong heading.', 'UA.V.C.K4', 'medium', 'Manufacturer guidance', true, true);

insert into ltf.choices (question_id, label, body, is_correct, rationale, sort_order, tier)
select q.id, v.label, v.body, v.is_correct, v.rationale, v.sort_order, v.tier
from ltf.questions q join (values
  ('reg-falsification', 'A', 'Suspension or revocation of any certificate, authorization, or waiver they hold', true, null, 1, null::smallint),
  ('reg-falsification', 'B', 'Nothing, because training records are never checked', false, 'Altering a record is itself a violation, checked or not.', 2, 1),
  ('reg-falsification', 'C', 'A warning letter only, since no flight took place', false, 'No flight is needed. The falsified record is the violation.', 3, 2),
  ('reg-falsification', 'D', 'Revocation of the remote pilot certificate only, leaving any waivers intact', false, '107.5 reaches any certificate, rating, authorization, or waiver held.', 4, 3),
  ('reg-records-on-request', 'A', 'Make the required documents and records available on request', true, null, 1, null::smallint),
  ('reg-records-on-request', 'B', 'Nothing; Part 107 operators keep no records the FAA can ask for', false, '107.7 expressly covers records and reports required by the regulations.', 2, 1),
  ('reg-records-on-request', 'C', 'Mail them to the nearest FSDO within 30 days', false, 'The obligation is to make them available on request, not to mail them within a set window.', 3, 2),
  ('reg-records-on-request', 'D', 'Make them available only if a safety event has been reported', false, 'The duty applies on any request, not only after a reported event.', 4, 3),
  ('reg-registration-any-weight', 'A', 'Yes; every aircraft flown under Part 107 must be registered, whatever it weighs', true, null, 1, null::smallint),
  ('reg-registration-any-weight', 'B', 'Only if it will be flown above 400 feet AGL', false, 'Altitude has nothing to do with registration.', 2, 1),
  ('reg-registration-any-weight', 'C', 'No; registration begins at 0.55 pounds', false, 'That threshold applies only to recreational flying.', 3, 2),
  ('reg-registration-any-weight', 'D', 'Yes, though the owner''s recreational registration number covers it', false, 'Part 107 aircraft are registered individually. A recreational registration covers only recreational flying.', 4, 3),
  ('reg-registration-marking', 'A', 'On an external surface of the aircraft', true, null, 1, null::smallint),
  ('reg-registration-marking', 'B', 'On the remote pilot certificate', false, 'The certificate is the pilot''s, not the aircraft''s marking.', 2, 1),
  ('reg-registration-marking', 'C', 'Inside the battery compartment, if it opens without tools', false, 'That was allowed before 2019. It must now be on an external surface.', 3, 2),
  ('reg-registration-marking', 'D', 'On the controller, so it can be shown to law enforcement', false, 'The number goes on the aircraft itself.', 4, 3),
  ('reg-condition-for-safe-operation', 'A', 'The remote pilot in command', true, null, 1, null::smallint),
  ('reg-condition-for-safe-operation', 'B', 'The FAA, through an annual inspection', false, 'There is no FAA annual inspection for a small UAS.', 2, 1),
  ('reg-condition-for-safe-operation', 'C', 'An FAA-certificated airframe and powerplant mechanic', false, 'Part 107 requires no certificated mechanic.', 3, 2),
  ('reg-condition-for-safe-operation', 'D', 'The person at the controls, if that person is not the rPIC', false, '107.15 puts the duty on the remote pilot in command.', 4, 3),
  ('reg-careless-reckless', 'A', 'Operating carelessly or recklessly so as to endanger life or property', true, null, 1, null::smallint),
  ('reg-careless-reckless', 'B', 'Failing to file a flight plan', false, 'Part 107 has no flight plan requirement.', 2, 1),
  ('reg-careless-reckless', 'C', 'The 400 foot altitude limit', false, 'Low passes do not break the altitude limit.', 3, 2),
  ('reg-careless-reckless', 'D', 'The prohibition on sustained flight over moving vehicles', false, 'A beach crowd is not moving vehicles. The conduct itself is careless or reckless.', 4, 3),
  ('reg-alcohol-timing', 'A', 'Yes, provided your blood alcohol concentration is below 0.04 percent', true, null, 1, null::smallint),
  ('reg-alcohol-timing', 'B', 'Yes, because Part 107 has no alcohol rules', false, '107.27 applies the 91.17 alcohol rules to Part 107 crew.', 2, 1),
  ('reg-alcohol-timing', 'C', 'No; Part 107 requires 24 hours between drinking and flying', false, 'The bottle to throttle rule is 8 hours.', 3, 2),
  ('reg-alcohol-timing', 'D', 'Yes, because 8 hours have passed, whatever your blood alcohol level', false, 'Both conditions apply: 8 hours and under 0.04 percent.', 4, 3),
  ('reg-night-requirements', 'A', 'The updated knowledge test or training, plus anti-collision lighting visible for 3 statute miles', true, null, 1, null::smallint),
  ('reg-night-requirements', 'B', 'A visual observer for every 15 minutes of flight', false, 'No such requirement exists.', 2, 1),
  ('reg-night-requirements', 'C', 'A night waiver issued under 107.200', false, 'That was the rule before April 2021.', 3, 2),
  ('reg-night-requirements', 'D', 'The updated test or training, plus anti-collision lighting visible for 1 statute mile', false, 'The lighting must be visible for 3 statute miles.', 4, 3),
  ('reg-property-for-hire', 'A', 'The aircraft and package must weigh under 55 pounds total, and the flight must stay within one state', true, null, 1, null::smallint),
  ('reg-property-for-hire', 'B', 'The package must be insured by the FAA', false, 'The FAA does not insure cargo.', 2, 1),
  ('reg-property-for-hire', 'C', 'Property may never be carried for pay under Part 107', false, 'Limited carriage for hire is allowed.', 3, 2),
  ('reg-property-for-hire', 'D', 'The flight may cross a state line if it stays within visual line of sight', false, 'Carriage for hire must stay within a single state.', 4, 3),
  ('reg-automated-flight', 'A', 'Be able to intervene at any time and keep the aircraft in visual line of sight', true, null, 1, null::smallint),
  ('reg-automated-flight', 'B', 'Nothing; automated flights are exempt from Part 107', false, 'Automation does not change who is responsible.', 2, 1),
  ('reg-automated-flight', 'C', 'A waiver, since automated flight is not permitted', false, 'Automated flight is permitted without a waiver.', 3, 2),
  ('reg-automated-flight', 'D', 'Keep visual line of sight through the live camera feed while automation flies', false, 'A camera feed never satisfies visual line of sight.', 4, 3),
  ('reg-tfr-overrides-laanc', 'A', 'The TFR applies; the LAANC authorization does not override it', true, null, 1, null::smallint),
  ('reg-tfr-overrides-laanc', 'B', 'TFRs apply only to manned aircraft', false, 'TFRs apply to unmanned aircraft too.', 2, 1),
  ('reg-tfr-overrides-laanc', 'C', 'You may fly if you stay below 200 feet AGL', false, 'A TFR has no low-altitude exception for drones.', 3, 2),
  ('reg-tfr-overrides-laanc', 'D', 'You may fly if you phone the issuing facility before launch', false, 'Notifying someone is not authorization. Fly only under the TFR''s stated conditions.', 4, 3),
  ('reg-airport-interference', 'A', 'Interfering with operations and traffic patterns at any airport, heliport, or seaplane base', true, null, 1, null::smallint),
  ('reg-airport-interference', 'B', 'Photographing aircraft parked on the ramp', false, 'Photography is not the issue. Interference is.', 2, 1),
  ('reg-airport-interference', 'C', 'Any flight within 5 statute miles of an airport without notifying the operator', false, 'Part 107 has no 5-mile notification rule.', 3, 2),
  ('reg-airport-interference', 'D', 'Interfering with traffic patterns at towered airports only', false, 'The rule covers every airport, heliport, and seaplane base.', 4, 3),
  ('reg-right-of-way-passing', 'A', 'Do not pass over, under, or ahead of another aircraft unless well clear', true, null, 1, null::smallint),
  ('reg-right-of-way-passing', 'B', 'Announce position on CTAF before every flight', false, 'Part 107 pilots are not required to transmit.', 2, 1),
  ('reg-right-of-way-passing', 'C', 'Climb above manned traffic to stay clear', false, 'Climbing toward traffic is the opposite of yielding.', 3, 2),
  ('reg-right-of-way-passing', 'D', 'Passing directly beneath manned aircraft is always permitted', false, 'Passing under is prohibited unless well clear.', 4, 3),
  ('reg-certificate-requirements', 'A', 'Pass the initial knowledge test and clear TSA security vetting', true, null, 1, null::smallint),
  ('reg-certificate-requirements', 'B', 'Log 40 hours of flight time with an instructor', false, 'No flight time is required.', 2, 1),
  ('reg-certificate-requirements', 'C', 'Hold a third-class medical certificate', false, 'No medical certificate is required.', 3, 2),
  ('reg-certificate-requirements', 'D', 'Pass a practical flight test with an FAA examiner', false, 'There is no practical test for the remote pilot certificate.', 4, 3),
  ('oop-night-over-people', 'A', 'Lit anti-collision lighting visible for at least 3 statute miles', true, null, 1, null::smallint),
  ('oop-night-over-people', 'B', 'Each person below must carry a flashlight', false, 'No such requirement exists.', 2, 1),
  ('oop-night-over-people', 'C', 'A waiver is always required', false, 'Night operations over people need no waiver if the requirements are met.', 3, 2),
  ('oop-night-over-people', 'D', 'Night operations over people are limited to Category 1 aircraft', false, 'Any eligible category may operate over people at night with proper lighting.', 4, 3),
  ('oop-kinetic-energy-measure', 'A', 'Injury severity equal to a rigid object transferring 11 foot-pounds on impact', true, null, 1, null::smallint),
  ('oop-kinetic-energy-measure', 'B', 'The propeller noise level at 50 feet', false, 'Noise is not part of the standard.', 2, 1),
  ('oop-kinetic-energy-measure', 'C', 'The aircraft''s top speed, regardless of its weight', false, 'Kinetic energy depends on both mass and speed.', 3, 2),
  ('oop-kinetic-energy-measure', 'D', 'Injury severity equal to a rigid object transferring 25 foot-pounds on impact', false, '25 foot-pounds is the Category 3 threshold.', 4, 3),
  ('oop-no-fixed-distance', 'A', 'None; eligibility comes from the aircraft''s category, not a set distance', true, null, 1, null::smallint),
  ('oop-no-fixed-distance', 'B', '1 statute mile', false, 'No such distance appears in the rule.', 2, 1),
  ('oop-no-fixed-distance', 'C', '25 feet', false, 'Part 107 sets no fixed lateral distance.', 3, 2),
